const embRes = $input.first().json;
const body = $('Webhook Timeline').first().json.body || {};
const topic = body.topic || '';
const proyecto = body.proyecto || null;
const n_results = body.n_results || 20; // mas chunks que en consulta normal

if (!embRes.data || !embRes.data[0]) {
  throw new Error(`Embedding response invalid`);
}

const payload = {
  query_embeddings: [embRes.data[0].embedding],
  n_results,
  include: ['documents', 'metadatas', 'distances']
};
if (proyecto) payload.where = { proyecto };

return [{ json: { topic, proyecto, chroma_payload: payload } }];

// Toma los chunks recuperados + le pide a Claude que extraiga EVENTOS con fecha sobre el topic.
const chromaRes = $input.first().json;
const body = $('Webhook Timeline').first().json.body || {};
const topic = body.topic || '';
const proyecto = body.proyecto || null;

const ids = (chromaRes.ids && chromaRes.ids[0]) || [];
const docs = (chromaRes.documents && chromaRes.documents[0]) || [];
const metas = (chromaRes.metadatas && chromaRes.metadatas[0]) || [];

if (ids.length === 0) {
  return [{ json: { topic, proyecto, eventos: [], mensaje: 'No encontre informacion sobre ese tema en tus fuentes.' } }];
}

// Construir contexto con TODA la metadata temporal disponible
const contexto = ids.map((id, i) => {
  const m = metas[i] || {};
  const fechaMeta = m.fecha || '';  // emails ya tienen fecha del header
  const archivoInfo = `archivo: ${m.archivo}${m.pagina ? `, pag ${m.pagina}` : ''}${m.hoja ? `, hoja ${m.hoja}` : ''}`;
  const fechaInfo = fechaMeta ? `, fecha del documento: ${fechaMeta}` : '';
  return `[${i+1}] (${archivoInfo}${fechaInfo})\n${docs[i]}`;
}).join('\n\n---\n\n');

const systemPrompt = `Sos un extractor temporal de eventos para CoWorkerIA.
El usuario quiere ver como evoluciono un tema/concepto a traves del tiempo segun sus documentos.
Te paso los pasajes recuperados con su metadata (archivo, fecha del documento si la hay).

Tu tarea: extraer EVENTOS DATABLES sobre el tema. Un evento es una afirmacion concreta con una fecha asociada (sea explicita en el texto o inferida de la fecha del documento).

Formato exacto JSON:
{
  "eventos": [
    {
      "fecha": "YYYY-MM-DD o YYYY-MM o YYYY o descripcion temporal si no hay fecha exacta (ej 'Q1 2026')",
      "fecha_iso": "YYYY-MM-DD para ordenar (aproxima si solo hay mes/año, ej '2026-01-01')",
      "valor": "el dato o estado especifico (ej: 'Presupuesto USD 80.000', 'Lider tecnico: Maria Lopez', 'Stack: AWS')",
      "descripcion": "contexto breve de que paso/se afirmo",
      "fuente_pasaje": numero (1-based) del pasaje origen,
      "fuente_archivo": "nombre del archivo",
      "fuente_pagina": numero o null
    }
  ],
  "resumen_evolucion": "1-2 frases describiendo como evoluciono el tema en total"
}

REGLAS:
- Solo eventos con fecha (explicita o inferida de la metadata).
- NO inventes fechas. Si un pasaje no tiene fecha y la metadata tampoco, no incluyas evento.
- Si dos eventos en la misma fecha dicen lo mismo, deduplicar.
- Si dos eventos en fechas distintas afirman valores distintos sobre el mismo aspecto, INCLUIR AMBOS (eso es la evolucion).
- Maximo 20 eventos.`;

const userPrompt = `TEMA A RASTREAR: ${topic}\n\nPASAJES DISPONIBLES:\n\n${contexto}\n\nExtrae eventos datables sobre el tema.`;

let eventos = [];
let resumen = '';
try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'http://localhost',
      'X-Title': 'CoWorkerIA Timeline',
    },
    body: {
      model: $env.LLM_MODEL || 'anthropic/claude-sonnet-4',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      max_tokens: 2000,
      temperature: 0,
    },
    json: true,
  });
  const raw = data.choices?.[0]?.message?.content || '{}';
  let parsed;
  try { parsed = JSON.parse(raw); }
  catch {
    const cleaned = raw.replace(/^```(?:json)?\s*/gm, '').replace(/```\s*$/gm, '').trim();
    try { parsed = JSON.parse(cleaned); }
    catch {
      let depth = 0, start = -1, found = null;
      for (let i = 0; i < cleaned.length; i++) {
        if (cleaned[i] === '{') { if (depth === 0) start = i; depth++; }
        else if (cleaned[i] === '}') { depth--; if (depth === 0 && start !== -1) { found = cleaned.slice(start, i + 1); break; } }
      }
      parsed = found ? (() => { try { return JSON.parse(found); } catch { return { eventos: [] }; } })() : { eventos: [] };
    }
  }
  eventos = Array.isArray(parsed.eventos) ? parsed.eventos : [];
  resumen = parsed.resumen_evolucion || '';
} catch (e) {
  return [{ json: { topic, proyecto, eventos: [], mensaje: `Error extrayendo eventos: ${e?.message}` } }];
}

// Ordenar por fecha_iso
eventos.sort((a, b) => String(a.fecha_iso || '').localeCompare(String(b.fecha_iso || '')));

// Detectar cambios: agrupar eventos por aspecto similar (mismo prefijo de 'valor')
const cambios = [];
for (let i = 1; i < eventos.length; i++) {
  const prev = eventos[i-1];
  const curr = eventos[i];
  // Mismo prefijo de valor (ej 'Presupuesto' vs 'Presupuesto') pero distinto valor completo
  const prefPrev = String(prev.valor || '').split(':')[0].trim().toLowerCase();
  const prefCurr = String(curr.valor || '').split(':')[0].trim().toLowerCase();
  if (prefPrev && prefPrev === prefCurr && prev.valor !== curr.valor) {
    cambios.push({
      aspecto: prefPrev,
      de: prev.valor,
      a: curr.valor,
      fecha_de: prev.fecha,
      fecha_a: curr.fecha,
      indice_evento_anterior: i - 1,
      indice_evento_nuevo: i,
    });
  }
}

return [{ json: { topic, proyecto, eventos, cambios, resumen_evolucion: resumen, total_chunks_analizados: ids.length } }];
